CREATE TABLE IF NOT EXISTS tablero_acceso (token TEXT PRIMARY KEY, rol TEXT NOT NULL, activo BOOLEAN NOT NULL DEFAULT true, creado TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO tablero_acceso (token, rol) SELECT md5(random()::text || clock_timestamp()::text || v.r), v.r FROM (VALUES ('produccion')) AS v(r)
WHERE NOT EXISTS (SELECT 1 FROM tablero_acceso a WHERE a.rol = v.r AND a.activo);
SELECT (SELECT token FROM tablero_acceso WHERE rol = 'produccion' AND activo ORDER BY creado LIMIT 1) AS t_prod,
       (SELECT token FROM tablero_acceso WHERE rol = 'auditor' AND activo ORDER BY creado LIMIT 1) AS t_auditor,
       (SELECT token FROM tablero_acceso WHERE rol = 'admin' AND activo ORDER BY creado LIMIT 1) AS t_admin;

