// Ligas de producción. produccion = captura; auditor = solo consulta; admin = la misma llave del tablero.
const cfg = $('Configuración (ligas)').first().json, a = $('Ligas').first().json;
const url = String(cfg.url_n8n || '').replace(/\/+$/, '') + '/webhook/produccion-tinacos?k=';
return [{ json: { produccion: url + a.t_prod, auditor: a.t_auditor ? url + a.t_auditor : '(sin llave de auditor)', administrador: a.t_admin ? url + a.t_admin : '(sin llave de admin)' } }];
